\begin{ex}%[9H5V1-3]
Tính diện tích của một tam giác đều, biết bán kính đường tròn ngoại tiếp tam giác đó là ${8}cm$. 
\choice
{  ${32 \sqrt{3}}cm$ }
   {  ${96 \sqrt{3}}cm$ }
     {  ${6 \sqrt{3}}cm$ }
    { \True ${48 \sqrt{3}}cm$  }
\loigiai{
\begin{tikzpicture}
    % Vẽ đường tròn tâm O bán kính 3
    \draw[thick] (0,0) circle (3);

    % Định nghĩa điểm O
    \coordinate [label=below right:$O$] (O) at (0,0);

    % Định nghĩa các đỉnh của tam giác đều ABC
    \coordinate [label=above:$A$] (A) at (90:3);
    \coordinate [label=below left:$B$] (B) at (210:3);
    \coordinate [label=below right:$C$] (C) at (330:3);

    % Vẽ tam giác ABC
    \draw[thick] (A) -- (B) -- (C) -- cycle;
    \coordinate [label=below:$H$] (H) at ($(B)!0.5!(C)$);

        % Vẽ đường cao AH
        \draw[ thick] (A) -- (H);
            \draw[ thick] (B) -- (O);
                \draw[ thick] (C) -- (O);
\end{tikzpicture}
Ta có $AO= \dfrac{2}{3} AH$ vậy $AH = 12cm$\\
$HB=AH \cot{60^{\circ} } =4 \sqrt{3}cm$\\
$S=\dfrac{1}{2}. BC.AH=HB.AH= 48 \sqrt{3}cm$
}\end{ex}

